function Invoke-Exp122ContainerStop {
    param([Parameter(Mandatory)][string]$Project,[string[]]$ComposeFiles=@(),[Parameter(Mandatory)][string]$Service,[Parameter(Mandatory)][string]$RunId,[Parameter(Mandatory)][string]$MetadataPath,[int]$GracePeriodSeconds=15,[int]$ProcessTimeoutSeconds=30,[Parameter(Mandatory)][string]$ContainerId,[string]$Executable='docker.exe',[string[]]$ArgumentsOverride=@())
    $started=(Get-Date).ToUniversalTime().ToString('o');$savedErrorAction=$ErrorActionPreference;$ErrorActionPreference='Continue';$inspectBefore=& docker.exe inspect --format '{{.State.Status}}' $ContainerId 2>$null;$inspectExitBefore=$LASTEXITCODE;$ErrorActionPreference=$savedErrorAction;$stateBefore=if($inspectExitBefore -eq 0){$inspectBefore.Trim()}else{'container not found'};$args=if($ArgumentsOverride.Count){$ArgumentsOverride}else{@('compose')+(@($ComposeFiles|ForEach-Object{@('-f',$_)})+@('-p',$Project,'stop','-t',[string]$GracePeriodSeconds,$Service))};$argString=($args|ForEach-Object{if($_ -match '[\s"]'){('"'+($_ -replace '"','\"')+'"')}else{$_}})-join ' '
    if($inspectExitBefore -ne 0){$value=[ordered]@{runId=$RunId;containerId=$ContainerId;command=($Executable+' '+$argString);startedAt=$started;completedAt=(Get-Date).ToUniversalTime().ToString('o');gracePeriodSeconds=$GracePeriodSeconds;processTimeoutSeconds=$ProcessTimeoutSeconds;timedOut=$false;exitCode=$null;stateBefore=$stateBefore;stateAfter='container not found';containerStillExists=$false;inspectExitCodeBefore=$inspectExitBefore;inspectExitCodeAfter=$inspectExitBefore;processTerminationAttempted=$false;processTerminationConfirmed=$false;stopStatus='APPLICATION_CONTAINER_DISAPPEARED'};$value|ConvertTo-Json -Depth 8|Set-Content $MetadataPath -Encoding UTF8;throw 'APPLICATION_CONTAINER_DISAPPEARED'}
    if($stateBefore -ne 'running'){$value=[ordered]@{runId=$RunId;containerId=$ContainerId;command=($Executable+' '+$argString);startedAt=$started;completedAt=(Get-Date).ToUniversalTime().ToString('o');gracePeriodSeconds=$GracePeriodSeconds;processTimeoutSeconds=$ProcessTimeoutSeconds;timedOut=$false;exitCode=$null;stateBefore=$stateBefore;stateAfter=$stateBefore;containerStillExists=$true;inspectExitCodeBefore=0;inspectExitCodeAfter=0;processTerminationAttempted=$false;processTerminationConfirmed=$false;stopStatus='APPLICATION_CONTAINER_PRESTOP_STATE_INVALID'};$value|ConvertTo-Json -Depth 8|Set-Content $MetadataPath -Encoding UTF8;throw 'APPLICATION_CONTAINER_PRESTOP_STATE_INVALID'}
    $psi=New-Object System.Diagnostics.ProcessStartInfo;$psi.FileName=$Executable;$psi.Arguments=$argString;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=New-Object System.Diagnostics.Process;$p.StartInfo=$psi;$null=$p.Start();$stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync();$timedOut=$false;$attempted=$false;$confirmed=$false;if(-not$p.WaitForExit($ProcessTimeoutSeconds*1000)){$timedOut=$true;$attempted=$true;try{$p.Kill();$p.WaitForExit();$confirmed=$p.HasExited}catch{}};$p.WaitForExit();$p.Refresh();$exit=if($timedOut){$null}else{$p.ExitCode};$savedErrorAction=$ErrorActionPreference;$ErrorActionPreference='Continue';$inspectAfter=& docker.exe inspect --format '{{.State.Status}}' $ContainerId 2>$null;$inspectExitAfter=$LASTEXITCODE;$ErrorActionPreference=$savedErrorAction;$stateAfter=if($inspectExitAfter -eq 0){$inspectAfter.Trim()}else{'container not found'};$completed=(Get-Date).ToUniversalTime().ToString('o');$exists=($inspectExitAfter -eq 0);$status=if($timedOut){'APPLICATION_CONTAINER_STOP_TIMEOUT'}elseif(-not$exists){'APPLICATION_CONTAINER_DISAPPEARED'}elseif($exit-ne0){'APPLICATION_CONTAINER_STOP_FAILED'}elseif($stateAfter -match 'running'){'APPLICATION_CONTAINER_STOP_FAILED'}else{'APPLICATION_CONTAINER_STOPPED'};$value=[ordered]@{runId=$RunId;containerId=$ContainerId;command=($Executable+' '+$argString);startedAt=$started;completedAt=$completed;gracePeriodSeconds=$GracePeriodSeconds;processTimeoutSeconds=$ProcessTimeoutSeconds;timedOut=$timedOut;exitCode=$exit;stateBefore=$stateBefore;stateAfter=$stateAfter;containerStillExists=$exists;inspectExitCodeBefore=$inspectExitBefore;inspectExitCodeAfter=$inspectExitAfter;processTerminationAttempted=$attempted;processTerminationConfirmed=$confirmed;stopStatus=$status;stdout=($stdout.Result);stderr=($stderr.Result)};$value|ConvertTo-Json -Depth 8|Set-Content $MetadataPath -Encoding UTF8;if($status-ne'APPLICATION_CONTAINER_STOPPED'){throw $status};$value
}
